"""Export the exact default model-visible prompt and current tool/sensor contracts."""
import hashlib
import json
from pathlib import Path

from single_token import make_prompt, format_prompt, actions_for


def export(root):
    config = json.loads((root/"configs/live_agent.json").read_text())
    contract = json.loads((root/"configs/process_inspection.json").read_text())
    prompt = format_prompt(make_prompt(config), "named")
    rows = ["# Current agent prompts and tools", "",
        "Generated by `scripts/agent/export_prompts.py`. Default: eight tools, canonical named histories, one unmasked action token. "
        "IDs and numerical timestamps stay in application transport/audits, outside model-visible history.", "",
        "## Exact default Ministral system prompt", "",
        "SHA-256: `"+hashlib.sha256(prompt.encode()).hexdigest()+"`", "", "```text", prompt, "```", "",
        "## Complete tool menu", "", "| Code | Tool | Work |", "| --- | --- | --- |"]
    descriptions = {tool["function"]["name"]: tool["function"]["description"] for tool in config["tools"]}
    for code, (tool, _, _) in actions_for(config).items():
        rows.append(f"| {code} | `{tool}()` | {descriptions[tool]} |")
    rows += ["", "Every schema requires only `reason` (string, maximum 240 characters; description requests at most 20 words). "
        "The default one-token proxy supplies `Selected action code {code}; no generated explanation`; the model generates no arguments. "
        "All tools remain available each turn. The native function-call transport remains supported explicitly.", "",
        "## Reason2 inspection prompts (unchanged)", "",
        "Each prompt receives three actual grayscale 448 x 256 images, in spot1/spot2/spot3 order. "
        "No agent history or extra system prompt is supplied. Labels are G/A/R, scored from next-token logits. "
        "The temperature bundle runs adhesive then weld as two separate inspections; no result substitutes for the other."]
    for stage, item in contract["stages"].items():
        rows += ["", f"### {stage}", "", f"SHA-256: `{item['prompt_sha256']}`", "", "```text", item["prompt"], "```"]
    return "\n".join(rows)+"\n"


if __name__ == "__main__":
    root = Path(__file__).resolve().parents[2]
    (root/"docs/current_agent_prompts.md").write_text(export(root))
